new:
# R164: 领域 JSON = 排除 skill_ids.json（其 skills 字段会重复计入总 skill 数 → 假 FAIL）
# 2026-09-22 第 10 轮：追加排除 index_manifest.json（无 skills 字段，混入会导致 1c 计数虚高与 3b「空域」假 FAIL）
function Get-DomainJsonFiles {
    @(Get-ChildItem "$global:skill_content\*.json" | Where-Object { $_.Name -notin @('skill_ids.json', 'index_manifest.json') })
}

Get-ChildItem "$SC\*.json" | Where-Object { $_.Name -notmatch '\.bak' -and $_.Name -notin @('skill_ids.json', 'index_manifest.json') } | ForEach-Object {
    $c = Get-Content $_.FullName -Raw | ConvertFrom-Json
    if ($null -ne $c.skills) { $total += $c.skills.Count }
}
